  @shape  cc = { evType, ppq, chan, val, shape, [tension], [muted], uuid, [plain], [...meta] }  @ 570
  @shape  noteSidecarPayload = { ppq, chan, pitch, droppedCount }  -- notesDeduped event  @ 575
  @shape  uuidsReassignedEvent = { ppq, chan, pitch, oldUuid, newUuid }  @ 576
  @shape  collisionEvent = { kind='killed'|'nudged', uuid, chan, pitch, ppq }  @ 577
  @shape  ccDedupEvent = { ppq, chan, evType, cc, pitch, droppedCount }  -- ccsDeduped event  @ 578
  @shape  reconcileEvent base = { kind, uuid, chan, evType, [cc], [pitch], ppq }  @ 579
